import{_ as i,c as a,o as t,ak as l}from"./chunks/framework.CjUXqSHI.js";const h=JSON.parse('{"title":"Delivery Semantics and Reliability","description":"How to design stable PURISTA systems with realistic broker guarantees","frontmatter":{"title":"Delivery Semantics and Reliability","description":"How to design stable PURISTA systems with realistic broker guarantees","order":209920},"headers":[],"relativePath":"handbook/2_building_business-logic/advanced/delivery-semantics-and-reliability.md","filePath":"handbook/2_building_business-logic/advanced/delivery-semantics-and-reliability.md","lastUpdated":1772015246000}'),r={name:"handbook/2_building_business-logic/advanced/delivery-semantics-and-reliability.md"};function n(s,e,o,d,c,m){return t(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="delivery-semantics-and-reliability" tabindex="-1">Delivery semantics and reliability <a class="header-anchor" href="#delivery-semantics-and-reliability" aria-label="Permalink to “Delivery semantics and reliability”">​</a></h1><h2 id="guarantee-model" tabindex="-1">Guarantee model <a class="header-anchor" href="#guarantee-model" aria-label="Permalink to “Guarantee model”">​</a></h2><p>End-to-end message delivery guarantees are a combination of:</p><ol><li>the selected PURISTA event bridge</li><li>broker/component configuration</li><li>your handler design (idempotency, retries, side effects)</li></ol><h2 id="common-modes" tabindex="-1">Common modes <a class="header-anchor" href="#common-modes" aria-label="Permalink to “Common modes”">​</a></h2><ul><li><code>at-most-once</code>: lower overhead, messages can be lost</li><li><code>at-least-once</code>: safer delivery, duplicates are expected</li><li><code>exactly-once</code>: rarely guaranteed end-to-end across distributed side effects</li></ul><h2 id="design-rules-for-production" tabindex="-1">Design rules for production <a class="header-anchor" href="#design-rules-for-production" aria-label="Permalink to “Design rules for production”">​</a></h2><ul><li>make command/subscription side effects idempotent</li><li>use deterministic business keys for deduplication</li><li>avoid non-atomic “read/modify/write” side effects without protection</li><li>set timeout and retry budgets intentionally</li><li>persist important business state outside process memory</li></ul><h2 id="streams-and-reliability" tabindex="-1">Streams and reliability <a class="header-anchor" href="#streams-and-reliability" aria-label="Permalink to “Streams and reliability”">​</a></h2><p>Current stream runtime support is available in <code>DefaultEventBridge</code> only.</p><p>For stream consumers:</p><ul><li>handle terminal frames (<code>complete</code>, <code>error</code>, <code>cancel</code>) explicitly</li><li>treat cancellation as a normal control path</li><li>validate chunk/final payloads where needed</li><li>keep chunk processing resilient to partial interruptions</li></ul><h2 id="minimal-acceptance-checklist" tabindex="-1">Minimal acceptance checklist <a class="header-anchor" href="#minimal-acceptance-checklist" aria-label="Permalink to “Minimal acceptance checklist”">​</a></h2><ul><li>broker-level delivery mode is documented for each environment</li><li>duplicate-handling strategy is tested</li><li>retry policy is tested against transient failures</li><li>operational runbook includes outage and reconnect behavior</li></ul>',14)])])}const b=i(r,[["render",n]]);export{h as __pageData,b as default};
